import * as React from "react";
import { Page, Card, BlockStack, Text } from "@xco-agency/corex-ui";
import { MOCK_ACTIVITIES } from "../constants";
import { ActivityFilters } from "../partials/ActivityFilters";
import { ActivityTimelineItem } from "../partials/ActivityTimelineItem";
import { ActivityEmptyState } from "../partials/ActivityEmptyState";
import { ActivityPayloadModal } from "../partials/ActivityPayloadModal";
import type { ActivityEventType, ActivityItemType } from "../types";
import { Banner } from "@xco-agency/corex-ui";
import { InlineStack } from "@xco-agency/corex-ui";

export function ActivityFeedExample() {
  const [activities, setActivities] = React.useState<ActivityItemType[]>(MOCK_ACTIVITIES);
  const [activeFilter, setActiveFilter] = React.useState<ActivityEventType>("all");
  const [isRefreshing, setIsRefreshing] = React.useState(false);
  const [inspectedItem, setInspectedItem] = React.useState<ActivityItemType | null>(null);
  const [feedbackNotice, setFeedbackNotice] = React.useState<string | null>(null);

  const handleRefresh = () => {
    setIsRefreshing(true);
    setTimeout(() => {
      setIsRefreshing(false);
      setFeedbackNotice("Activity feed refreshed with latest events.");
      setTimeout(() => setFeedbackNotice(null), 3500);
    }, 500);
  };

  const handleActionClick = (actionLabel: string, item: ActivityItemType) => {
    setFeedbackNotice(`Clicked "${actionLabel}" for ${item.title}`);
    setTimeout(() => setFeedbackNotice(null), 3000);
  };

  const filteredActivities = React.useMemo(() => {
    if (activeFilter === "all") return activities;
    return activities.filter((act) => act.eventType === activeFilter);
  }, [activities, activeFilter]);

  const groupedActivities = React.useMemo(() => {
    const groups: Record<string, ActivityItemType[]> = {};
    for (const act of filteredActivities) {
      if (!groups[act.dateGroup]) {
        groups[act.dateGroup] = [];
      }
      groups[act.dateGroup]!.push(act);
    }
    return groups;
  }, [filteredActivities]);

  const dateGroups = Object.keys(groupedActivities);

  return (
    <Page inlineSize="small">
      {/* Floating / Inline Action Notification Feedback */}
      {feedbackNotice && (
        <Banner dismissible onDismiss={() => setFeedbackNotice(null)} tone="info">
          {feedbackNotice}
        </Banner>
      )}

      {/* Main Card Surface */}
      <Card>
        <BlockStack gap="base">
          {/* Top Bar: Recent Activity Header + Filter & Refresh Buttons */}
          <ActivityFilters
            activeFilter={activeFilter}
            onSelectFilter={setActiveFilter}
            onRefresh={handleRefresh}
            isRefreshing={isRefreshing}
          />

          {filteredActivities.length === 0 ? (
            <ActivityEmptyState onReset={() => setActiveFilter("all")} />
          ) : (
            <BlockStack gap="large-100">
              {dateGroups.map((dateGroup) => {
                const items = groupedActivities[dateGroup] ?? [];
                return (
                  <div key={dateGroup}>
                    {/* Date Section Heading */}
                    <InlineStack paddingBlockEnd="small">
                      <Text variant="base" heading>
                        {dateGroup}
                      </Text>
                    </InlineStack>

                    {/* Connected Timeline Flow */}
                    {items.map((item, index) => {
                      const isLastItem = index === items.length - 1;
                      return (
                        <ActivityTimelineItem
                          key={item.id}
                          item={item}
                          isLast={isLastItem}
                          onActionClick={handleActionClick}
                          onViewPayload={setInspectedItem}
                        />
                      );
                    })}
                  </div>
                );
              })}
            </BlockStack>
          )}
        </BlockStack>
      </Card>

      {/* JSON Payload Inspector Modal */}
      <ActivityPayloadModal
        open={inspectedItem !== null}
        item={inspectedItem}
        onClose={() => setInspectedItem(null)}
      />
    </Page>
  );
}

export * from "./types";
export * from "./constants";
export { ActivityFilters } from "./partials/ActivityFilters";
export { ActivityTimelineItem } from "./partials/ActivityTimelineItem";
export { ActivityPayloadModal } from "./partials/ActivityPayloadModal";
export { ActivityEmptyState } from "./partials/ActivityEmptyState";
export { ActivityFeedExample } from "./examples/ActivityFeedExample";

import * as React from "react";
import { EmptyState, Text } from "@xco-agency/corex-ui";
import type { ActivityEmptyStatePropsType } from "../types";

export function ActivityEmptyState({
  onReset,
}: ActivityEmptyStatePropsType) {
  return (
    <EmptyState
      heading="No activity found"
      image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
      action={{
        content: "Reset filter",
        onAction: onReset,
        variant: "secondary",
      }}
      padding="large-100"
    >
      <Text as="p" tone="neutral" variant="small">
        There are no activity events matching the selected filter. Try selecting "All activities" or refreshing.
      </Text>
    </EmptyState>
  );
}

import * as React from "react";
import {
  InlineStack,
  Text,
  Button,
} from "@xco-agency/corex-ui";
import { FILTER_OPTIONS } from "../constants";
import type { ActivityFiltersPropsType } from "../types";

export function ActivityFilters({
  activeFilter,
  onSelectFilter,
  onRefresh,
  isRefreshing,
}: ActivityFiltersPropsType) {
  const [filterOpen, setFilterOpen] = React.useState(false);
  const dropdownRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setFilterOpen(false);
      }
    }
    if (filterOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [filterOpen]);

  const activeOption = FILTER_OPTIONS.find((opt) => opt.value === activeFilter);
  const filterButtonLabel =
    activeFilter === "all" ? "Filter" : `Filter: ${activeOption?.label ?? ""}`;

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        width: "100%",
        paddingBottom: "8px",
      }}
    >
      <Text variant="large" heading>
        Recent Activity
      </Text>

      <InlineStack gap="small-200" alignItems="center">
        {/* Filter Dropdown */}
        <div ref={dropdownRef} style={{ position: "relative" }}>
          <Button
            variant="secondary"
            size="small"
            onClick={() => setFilterOpen((prev) => !prev)}
          >
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "6px",
              }}
            >
              <span>{filterButtonLabel}</span>
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <polyline points="6 9 12 15 18 9" />
              </svg>
            </span>
          </Button>

          {filterOpen && (
            <div
              style={{
                position: "absolute",
                right: 0,
                top: "calc(100% + 4px)",
                zIndex: 100,
                backgroundColor: "var(--p-color-bg-surface, #ffffff)",
                border: "1px solid var(--p-color-border-subdued, #e1e3e5)",
                borderRadius: "8px",
                boxShadow: "0 4px 16px rgba(0, 0, 0, 0.08)",
                minWidth: "190px",
                padding: "4px 0",
                overflow: "hidden",
              }}
            >
              {FILTER_OPTIONS.map((opt) => {
                const isSelected = activeFilter === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => {
                      onSelectFilter(opt.value);
                      setFilterOpen(false);
                    }}
                    style={{
                      width: "100%",
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      padding: "8px 14px",
                      background: isSelected
                        ? "var(--p-color-bg-surface-secondary, #f6f6f7)"
                        : "transparent",
                      border: "none",
                      cursor: "pointer",
                      fontSize: "13px",
                      fontWeight: isSelected ? 600 : 400,
                      color: "var(--p-color-text, #202223)",
                    }}
                  >
                    <span>{opt.label}</span>
                    {isSelected && (
                      <span
                        style={{
                          color: "var(--p-color-text-success, #108043)",
                          fontWeight: 700,
                        }}
                      >
                        ✓
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Refresh Button */}
        <Button
          variant="secondary"
          size="small"
          onClick={onRefresh}
          accessibilityLabel="Refresh activities"
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              display: "block",
              transition: "transform 0.4s ease",
              transform: isRefreshing ? "rotate(360deg)" : "none",
            }}
          >
            <path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
            <path d="M3 3v5h5" />
            <path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16" />
            <path d="M16 16h5v5" />
          </svg>
        </Button>
      </InlineStack>
    </div>
  );
}

import * as React from "react";
import { Modal, BlockStack, Text, Badge, InlineStack } from "@xco-agency/corex-ui";
import type { ActivityPayloadModalPropsType } from "../types";

export function ActivityPayloadModal({
  open,
  item,
  onClose,
}: ActivityPayloadModalPropsType) {
  const [copied, setCopied] = React.useState(false);

  if (!item || !item.payload) return null;

  const jsonString = JSON.stringify(item.payload, null, 2);

  const handleCopy = () => {
    navigator.clipboard?.writeText(jsonString);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={`Event Payload: ${item.title}`}
      primaryAction={{
        content: copied ? "Copied to clipboard!" : "Copy payload JSON",
        onAction: handleCopy,
      }}
      secondaryActions={[
        {
          content: "Close",
          onAction: onClose,
        },
      ]}
    >
      <BlockStack gap="base">
        <InlineStack gap="small-200" alignItems="center">
          <Badge tone={item.badgeTone}>{item.badgeText}</Badge>
          <Text variant="small" tone="neutral">
            Event ID: {item.id} • {item.timestamp}
          </Text>
        </InlineStack>

        <pre
          style={{
            background: "var(--p-color-bg-surface-secondary)",
            padding: "16px",
            borderRadius: "var(--p-border-radius-100)",
            border: "1px solid var(--p-color-border-subdued)",
            fontSize: "12px",
            fontFamily: "monospace",
            overflowX: "auto",
            margin: 0,
            lineHeight: 1.5,
          }}
        >
          {jsonString}
        </pre>
      </BlockStack>
    </Modal>
  );
}

import * as React from "react";
import {
  InlineStack,
  Text,
  Badge,
  Button,
  Box,
  BlockStack,
  Icon,
  IconTile,
} from "@xco-agency/corex-ui";
import type { ActivityTimelineItemPropsType } from "../types";
import { Divider } from "@xco-agency/corex-ui";

export function ActivityTimelineItem({
  item,
  isLast = false,
  onActionClick,
  onViewPayload,
}: ActivityTimelineItemPropsType) {
  return (
    <InlineStack gap="small" alignItems="stretch" position="relative">
      {/* Left Timeline Node & Connecting Line */}
      <BlockStack shrink inlineSize="28px" alignItems="center">
        <Box
          blockSize="28px"
          inlineSize="28px"
          background="base"
          border="base"
          borderRadius="large-200"
        >
          <InlineStack alignItems="center" justifyContent="center" blockSize="27px">
            <Icon type={item.icon} tone={item.iconTone} />
          </InlineStack>
        </Box>

        {!isLast && (
          <div
            style={{
              width: "1px",
              flex: 1,
              backgroundColor: "var(--p-color-border-subdued, #e1e3e5)",
              margin: "4px 0",
              minHeight: "24px",
            }}
          />
        )}
      </BlockStack>

      {/* Right Content Area */}
      <BlockStack flex={1} paddingBlockEnd={isLast ? "small-300" : "base"}>
        {/* Top Header Row: Title, Badge, and Timestamp */}
        <InlineStack
          justifyContent="space-between"
          alignItems="center"
          gap="small-200"
          wrap
        >
          <InlineStack gap="small-200" alignItems="center">
            <Text variant="base" heading>
              {item.title}
            </Text>

            <Badge tone={item.badgeTone}>{item.badgeText}</Badge>
          </InlineStack>

          <Text as="span" variant="small" color="subdued">
            {item.timestamp}
          </Text>
        </InlineStack>

        {/* Subtitle / Description Text */}
        <Text color="subdued">{item.description}</Text>

        {/* Key-Value Details Container */}
        {item.details && item.details.length > 0 && (
          <BlockStack paddingBlock="small">
            <Box background="base" border="base" borderRadius="large" overflow="hidden">
              {item.details.map((detail, idx) => (
                <React.Fragment key={idx}>
                  <Box>
                    <InlineStack
                      justifyContent="space-between"
                      alignItems="center"
                      gap="small-200"

                      paddingBlock="small-200"
                      paddingInline="small"
                    >
                      <Text as="span" variant="small" color="subdued">
                        {detail.label}
                      </Text>
                      <Text variant="small" heading>
                        {detail.value}
                      </Text>
                    </InlineStack>
                  </Box>
                  {idx < item.details!.length - 1 && <Divider />}
                </React.Fragment>
              ))}
            </Box>
          </BlockStack>
        )}

        {/* Action Buttons Row */}
        {item.actions && item.actions.length > 0 && (
          <InlineStack gap="small-200" alignItems="center">
            {item.actions.map((act, idx) => (
              <Button
                key={idx}
                variant={act.variant ?? "secondary"}
                size="small"
                onClick={() => {
                  if (act.onClick) act.onClick();
                  if (onActionClick) onActionClick(act.label, item);
                }}
              >
                {act.label}
              </Button>
            ))}

            {item.payload && onViewPayload && (
              <Button variant="tertiary" size="small" onClick={() => onViewPayload(item)}>
                JSON Payload
              </Button>
            )}
          </InlineStack>
        )}
      </BlockStack>
    </InlineStack>
  );
}

import { IconType } from "@xco-agency/corex-ui";

export type ActivityDetailFieldType = {
  label: string;
  value: string;
};

export type ActivityActionType = {
  label: string;
  variant?: "primary" | "secondary" | "tertiary";
  onClick?: () => void;
};

export type ActivityEventType =
  "all" | "order" | "payment" | "inventory" | "message" | "fulfillment";

export type ActivityItemType = {
  id: string;
  title: string;
  badgeText: string;
  badgeTone?: "info" | "success" | "warning" | "critical" | "neutral";
  timestamp: string;
  dateGroup: "Today" | "Yesterday" | "Earlier this week";
  description: string;
  icon: IconType;
  iconTone?: "info" | "success" | "warning" | "critical" | "neutral";
  details?: ActivityDetailFieldType[];
  actions?: ActivityActionType[];
  eventType: ActivityEventType;
  payload?: Record<string, unknown>;
};

export type ActivityFiltersType = {
  eventType: ActivityEventType;
};

export type ActivityFiltersPropsType = {
  activeFilter: ActivityEventType;
  onSelectFilter: (eventType: ActivityEventType) => void;
  onRefresh: () => void;
  isRefreshing?: boolean;
};

export type ActivityTimelineItemPropsType = {
  item: ActivityItemType;
  isLast?: boolean;
  onActionClick?: (actionLabel: string, item: ActivityItemType) => void;
  onViewPayload?: (item: ActivityItemType) => void;
};

export type ActivityPayloadModalPropsType = {
  open: boolean;
  item: ActivityItemType | null;
  onClose: () => void;
};

export type ActivityEmptyStatePropsType = {
  onReset: () => void;
};
